  droppedBySection: Record<keyof ContextPressureRecoverySection, number>;
}

export type ContextPressureRecoveryResult =
  | {
      status: "recovered";
      complete: false;
      truncated: boolean;
      digest: string;
      sections: ContextPressureRecoverySection;
      kept: number;
      dropped: number;
      total: number;
      counts: ContextPressureRecoveryCounts;
    }
  | {
      status: "unknown";
      complete: false;
      truncated: false;
      digest: string;
      kept: 0;
      dropped: 0;
      total: 0;
      counts: ContextPressureRecoveryCounts;
    }
  | {
      status: "depth-exceeded";
      complete: false;
      truncated: false;
      digest: string;
      depth: number;
      maxDepth: number;
      kept: 0;
      dropped: 0;
      total: 0;
      counts: ContextPressureRecoveryCounts;
    };

const SECTION_NAMES: Array<keyof ContextPressureRecoverySection> = [
  "goal",
  "unfinishedWork",
  "dependencies",
  "recentEvidence",
];

const EMPTY_COUNTS = (): ContextPressureRecoveryCounts => ({
  kept: 0,
  dropped: 0,
  total: 0,
  bySection: { goal: 0, unfinishedWork: 0, dependencies: 0, recentEvidence: 0 },
  droppedBySection: { goal: 0, unfinishedWork: 0, dependencies: 0, recentEvidence: 0 },
});

function canonicalize(value: unknown): string {
  if (value === null) return "null";
  if (typeof value === "string") return JSON.stringify(value);
  if (typeof value === "number") {
    if (!Number.isFinite(value)) return JSON.stringify(String(value));
    return JSON.stringify(value);
  }
  if (typeof value === "boolean") return JSON.stringify(value);
  if (typeof value === "bigint") return JSON.stringify(value.toString());
  if (typeof value === "undefined") return '"__undefined__"';
  if (Array.isArray(value)) return `[${value.map(canonicalize).join(",")}]`;
  if (typeof value === "object") {
    const record = value as Record<string, unknown>;
    return `{${Object.keys(record)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${canonicalize(record[key])}`)
      .join(",")}}`;
  }
  return JSON.stringify(String(value));
}

function digestOf(value: unknown): string {
  return createHash("sha256").update(canonicalize(value)).digest("hex");
}

function unwrapSnapshot(snapshot: ContextPressureRecoverySnapshot | null | undefined): ContextPressureRecoverySnapshot | null {
  if (!snapshot || typeof snapshot !== "object") return null;
  const nested = snapshot.workingContext;
  if (nested && typeof nested === "object") {
    return { ...nested, ...snapshot, workingContext: undefined };
  }
  return snapshot;
}

function asItems(value: unknown): string[] {
  if (value === null || value === undefined) return [];
  const values = Array.isArray(value) ? value : [value];
  return values
    .filter((item) => item !== null && item !== undefined && item !== "")
    .map((item) => (typeof item === "string" ? item : canonicalize(item)));
}

function firstItems(snapshot: ContextPressureRecoverySnapshot, keys: string[]): string[] {
  for (const key of keys) {
    const value = snapshot[key];
    const items = asItems(value);
    if (items.length > 0) return items;
  }
  return [];
}

function snapshotSections(snapshot: ContextPressureRecoverySnapshot): ContextPressureRecoverySection {
  return {
    goal: firstItems(snapshot, ["goal", "goals", "objective", "objectives"]),
    unfinishedWork: firstItems(snapshot, [
      "unfinishedWork",
      "unfinished",
      "pendingWork",
      "incompleteWork",
    ]),
    dependencies: firstItems(snapshot, ["dependencies", "dependency"]),
    recentEvidence: firstItems(snapshot, ["recentEvidence", "evidence"]),
  };
}

function observedDepth(snapshot: ContextPressureRecoverySnapshot): number {
  const candidates: number[] = [];
  const explicit = snapshot.handoffDepth;
  if (typeof explicit === "number" && Number.isFinite(explicit)) candidates.push(explicit);
  const handoffDepth = snapshot.handoff?.depth;
  if (typeof handoffDepth === "number" && Number.isFinite(handoffDepth)) candidates.push(handoffDepth);
  if (Array.isArray(snapshot.handoffChain)) candidates.push(snapshot.handoffChain.length);
  if (Array.isArray(snapshot.handoff?.chain)) candidates.push(snapshot.handoff.chain.length);
  if (typeof snapshot.depth === "number" && Number.isFinite(snapshot.depth)) candidates.push(snapshot.depth);
  return candidates.length > 0 ? Math.max(...candidates) : 0;
}

function boundedInteger(value: number | undefined, fallback: number): number {
  if (value === undefined || !Number.isFinite(value)) return fallback;
  return Math.max(0, Math.floor(value));
}

/**
 * Projects a bounded, deterministic recovery summary from an existing Working
 * Context snapshot. The function never mutates the snapshot and never marks the
 * underlying task complete.
 */
export function recoverContextPressure(
  snapshot: ContextPressureRecoverySnapshot | null | undefined,
  options: ContextPressureRecoveryOptions = {},
): ContextPressureRecoveryResult {
  const maxDepth = boundedInteger(options.maxDepth, 8);
  const maxItems = boundedInteger(options.maxItems, 32);
  const current = unwrapSnapshot(snapshot);
  const depth = current ? observedDepth(current) : 0;
  const digest = digestOf({
    snapshot: current,
    maxDepth,
    maxItems,
    projection: SECTION_NAMES,
  });

  if (depth > maxDepth) {
    return {
      status: "depth-exceeded",
      complete: false,
      truncated: false,
      digest,
      depth,
      maxDepth,
      kept: 0,
      dropped: 0,
      total: 0,
      counts: EMPTY_COUNTS(),
    };
  }

  if (!current) {
    return {
      status: "unknown",
      complete: false,
      truncated: false,
      digest,
      kept: 0,
      dropped: 0,
      total: 0,
      counts: EMPTY_COUNTS(),
    };
  }

  const source = snapshotSections(current);
  const total = SECTION_NAMES.reduce((sum, name) => sum + source[name].length, 0);
  if (total === 0) {
    return {
      status: "unknown",
      complete: false,
      truncated: false,
      digest,
      kept: 0,
      dropped: 0,
      total: 0,
      counts: EMPTY_COUNTS(),
    };
  }

  const sections: ContextPressureRecoverySection = {
    goal: [],
    unfinishedWork: [],
    dependencies: [],
    recentEvidence: [],
  };
  const counts = EMPTY_COUNTS();
  let remaining = maxItems;

  for (const name of SECTION_NAMES) {
    for (const item of source[name]) {
      if (remaining > 0) {
        sections[name].push(item);
        counts.bySection[name] += 1;
        counts.kept += 1;
        remaining -= 1;
      } else {
        counts.droppedBySection[name] += 1;
        counts.dropped += 1;
      }
    }
  }
  counts.total = total;

  return {
    status: "recovered",
    complete: false,
    truncated: counts.dropped > 0,
    digest,
    sections,
    kept: counts.kept,
    dropped: counts.dropped,
    total: counts.total,
    counts,
  };
}

export const projectContextPressureRecovery = recoverContextPressure;
export const recoverWorkingContext = recoverContextPressure;
