}

export interface ContextPressureRecoveryOptions {
  /** Maximum permitted handoff-chain depth. */
  maxDepth?: number;
  /** Maximum number of items retained across all four sections. */
  maxItems?: number;
}

export interface ContextPressureRecoverySection {
  goal: string[];
  unfinishedWork: string[];
  dependencies: string[];
  recentEvidence: string[];
}

export interface ContextPressureRecoveryCounts {
  kept: number;
  dropped: number;
  total: number;
