      sections: ContextPressureRecoverySection;
      kept: number;
      dropped: number;
      total: number;
      counts: ContextPressureRecoveryCounts;
    }
  | {
      status: "unknown";
      complete: false;
      truncated: false;
      digest: string;
      kept: 0;
      dropped: 0;
      total: 0;
      counts: ContextPressureRecoveryCounts;
    }
  | {
      status: "depth-exceeded";
      complete: false;
      truncated: false;
      digest: string;
      depth: number;
      maxDepth: number;
      kept: 0;
      dropped: 0;
      total: 0;
      counts: ContextPressureRecoveryCounts;
    };

const SECTION_NAMES: Array<keyof ContextPressureRecoverySection> = [
  "goal",
  "unfinishedWork",
  "dependencies",
  "recentEvidence",
];

const EMPTY_COUNTS = (): ContextPressureRecoveryCounts => ({
  kept: 0,
  dropped: 0,
  total: 0,
  bySection: { goal: 0, unfinishedWork: 0, dependencies: 0, recentEvidence: 0 },
  droppedBySection: { goal: 0, unfinishedWork: 0, dependencies: 0, recentEvidence: 0 },
});

function canonicalize(value: unknown): string {
  if (value === null) return "null";
  if (typeof value === "string") return JSON.stringify(value);
  if (typeof value === "number") {
    if (!Number.isFinite(value)) return JSON.stringify(String(value));
    return JSON.stringify(value);
  }
  if (typeof value === "boolean") return JSON.stringify(value);
  if (typeof value === "bigint") return JSON.stringify(value.toString());
  if (typeof value === "undefined") return '"__undefined__"';
  if (Array.isArray(value)) return `[${value.map(canonicalize).join(",")}]`;
  if (typeof value === "object") {
    const record = value as Record<string, unknown>;
    return `{${Object.keys(record)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${canonicalize(record[key])}`)
      .join(",")}}`;
  }
  return JSON.stringify(String(value));
}

function digestOf(value: unknown): string {
  return createHash("sha256").update(canonicalize(value)).digest("hex");
}

function unwrapSnapshot(snapshot: ContextPressureRecoverySnapshot | null | undefined): ContextPressureRecoverySnapshot | null {
  if (!snapshot || typeof snapshot !== "object") return null;
  const nested = snapshot.workingContext;
  if (nested && typeof nested === "object") {
    return { ...nested, ...snapshot, workingContext: undefined };
  }
  return snapshot;
}

function asItems(value: unknown): string[] {
  if (value === null || value === undefined) return [];
  const values = Array.isArray(value) ? value : [value];
  return values
    .filter((item) => item !== null && item !== undefined && item !== "")
    .map((item) => (typeof item === "string" ? item : canonicalize(item)));
}

function firstItems(snapshot: ContextPressureRecoverySnapshot, keys: string[]): string[] {
  for (const key of keys) {
    const value = snapshot[key];
    const items = asItems(value);
    if (items.length > 0) return items;
  }
  return [];
}

function snapshotSections(snapshot: ContextPressureRecoverySnapshot): ContextPressureRecoverySection {
  return {
    goal: firstItems(snapshot, ["goal", "goals", "objective", "objectives"]),
    unfinishedWork: firstItems(snapshot, [
      "unfinishedWork",
      "unfinished",
      "pendingWork",
      "incompleteWork",
    ]),
    dependencies: firstItems(snapshot, ["dependencies", "dependency"]),
    recentEvidence: firstItems(snapshot, ["recentEvidence", "evidence"]),
  };
}

function observedDepth(snapshot: ContextPressureRecoverySnapshot): number {
  const candidates: number[] = [];
  const explicit = snapshot.handoffDepth;
  if (typeof explicit === "number" && Number.isFinite(explicit)) candidates.push(explicit);
