  snapshot: ContextPressureRecoverySnapshot | null | undefined,
  options: ContextPressureRecoveryOptions = {},
): ContextPressureRecoveryResult {
  const maxDepth = boundedInteger(options.maxDepth, 8);
  const maxItems = boundedInteger(options.maxItems, 32);
  const current = unwrapSnapshot(snapshot);
  const depth = current ? observedDepth(current) : 0;
  const digest = digestOf({
    snapshot: current,
    maxDepth,
    maxItems,
    projection: SECTION_NAMES,
  });

