    return {
      status: "depth-exceeded",
      complete: false,
      truncated: false,
      digest,
      depth,
      maxDepth,
      kept: 0,
      dropped: 0,
      total: 0,
      counts: EMPTY_COUNTS(),
    };
  }

  if (!current) {
    return {
      status: "unknown",
      complete: false,
      truncated: false,
      digest,
      kept: 0,
      dropped: 0,
      total: 0,
      counts: EMPTY_COUNTS(),
    };
  }

  const source = snapshotSections(current);
  const total = SECTION_NAMES.reduce((sum, name) => sum + source[name].length, 0);
  if (total === 0) {
    return {
      status: "unknown",
      complete: false,
      truncated: false,
      digest,
      kept: 0,
      dropped: 0,
      total: 0,
      counts: EMPTY_COUNTS(),
    };
  }

  const sections: ContextPressureRecoverySection = {
    goal: [],
    unfinishedWork: [],
    dependencies: [],
    recentEvidence: [],
  };
  const counts = EMPTY_COUNTS();
  let remaining = maxItems;

  for (const name of SECTION_NAMES) {
    for (const item of source[name]) {
      if (remaining > 0) {
        sections[name].push(item);
        counts.bySection[name] += 1;
        counts.kept += 1;
        remaining -= 1;
      } else {
        counts.droppedBySection[name] += 1;
        counts.dropped += 1;
      }
    }
  }
  counts.total = total;

  return {
    status: "recovered",
    complete: false,
    truncated: counts.dropped > 0,
    digest,
    sections,
    kept: counts.kept,
    dropped: counts.dropped,
    total: counts.total,
    counts,
  };
}

export const projectContextPressureRecovery = recoverContextPressure;
export const recoverWorkingContext = recoverContextPressure;
